"""Chromium os_crypt: recover the profile key and decrypt stored passwords and cookies.

Windows Chromium (Chrome, Edge, Brave, Vivaldi, Opera, ...) stores a random AES-256 key
in the ``Local State`` file under ``os_crypt.encrypted_key``: base64 of the literal
``DPAPI`` followed by a DPAPI blob of the key. Saved passwords (``Login Data``) and
cookies (``Cookies``) are then AES-256-GCM encrypted with that key, each value carrying
the ASCII prefix ``v10``.

Chrome 127+ adds App-Bound Encryption: a second key under
``os_crypt.app_bound_encrypted_key`` and values prefixed ``v20``. Unwrapping it needs the
SYSTEM account and the browser's elevation service, so this module reports ``v20`` values
as present and does not decrypt them.

Before os_crypt (Chrome < 80 on Windows), each saved value was an individual DPAPI blob;
those decrypt directly with the user master key and are handled by :func:`decrypt_value`.

Cookies: at Cookies-database schema ``version`` >= 24 (Chrome ~130+) the decrypted cookie
plaintext begins with a 32-byte SHA-256 of the cookie's ``host_key``, which
:func:`strip_cookie_host_hash` removes. Earlier schema versions have no such prefix.
"""
import base64
import json

from Crypto.Cipher import AES

from .blob import DpapiBlob

DPAPI_KEY_PREFIX = b'DPAPI'
V10 = b'v10'
V20 = b'v20'
_DPAPI_BLOB_MAGIC = b'\x01\x00\x00\x00'   # a DPAPI blob opens with dwVersion == 1
_GCM_NONCE_LEN = 12
_GCM_TAG_LEN = 16
_COOKIE_HOST_HASH_LEN = 32
_COOKIE_HOST_HASH_MIN_DB_VERSION = 24


def load_os_crypt(local_state):
    """Return the ``os_crypt`` dict from a Local State path, bytes, JSON str, or dict."""
    if isinstance(local_state, dict):
        data = local_state
    elif isinstance(local_state, (bytes, bytearray)):
        data = json.loads(bytes(local_state).decode('utf-8', 'replace'))
    elif isinstance(local_state, str) and local_state.lstrip()[:1] == '{':
        data = json.loads(local_state)
    else:
        with open(local_state, 'r', encoding='utf-8') as handle:
            data = json.load(handle)
    return data.get('os_crypt', {}) or {}


def os_crypt_key(local_state, mk_pool, entropy=None):
    """Recover the DPAPI-wrapped AES key. Return ``(key_or_None, info)``.

    ``info`` always carries ``app_bound`` (whether an App-Bound key is present). When the
    key blob is found it also carries ``mk_guid`` and ``have_master_key``.
    """
    oc = load_os_crypt(local_state)
    info = {'app_bound': bool(oc.get('app_bound_encrypted_key'))}
    encoded = oc.get('encrypted_key')
    if not encoded:
        return None, info
    raw = base64.b64decode(encoded)
    if raw[:len(DPAPI_KEY_PREFIX)] != DPAPI_KEY_PREFIX:
        info['key_prefix'] = raw[:5]
        return None, info
    blob = DpapiBlob(raw[len(DPAPI_KEY_PREFIX):])
    info['mk_guid'] = blob.mk_guid
    master_key = mk_pool.get_key(blob.mk_guid)
    info['have_master_key'] = master_key is not None
    if master_key is None:
        return None, info
    return blob.decrypt(master_key, entropy=entropy), info


def value_scheme(value):
    """Classify a stored encrypted value: 'v10', 'v20', 'dpapi', 'empty' or 'unknown'."""
    if not value:
        return 'empty'
    if value[:3] == V10:
        return 'v10'
    if value[:3] == V20:
        return 'v20'
    if value[:4] == _DPAPI_BLOB_MAGIC:
        return 'dpapi'
    return 'unknown'


def decrypt_gcm(value, key):
    """Decrypt a ``v10``/``v20`` wire value (prefix + nonce + ciphertext + tag)."""
    if key is None or len(value) < 3 + _GCM_NONCE_LEN + _GCM_TAG_LEN:
        return None
    nonce = value[3:3 + _GCM_NONCE_LEN]
    tag = value[-_GCM_TAG_LEN:]
    cipher_text = value[3 + _GCM_NONCE_LEN:-_GCM_TAG_LEN]
    try:
        return AES.new(key, AES.MODE_GCM, nonce=nonce).decrypt_and_verify(cipher_text, tag)
    except ValueError:
        return None


def decrypt_value(value, key=None, mk_pool=None, entropy=None):
    """Decrypt one stored value by its scheme. Return ``(plaintext_or_None, scheme)``.

    ``v10`` uses the os_crypt ``key``. A legacy per-value DPAPI blob (scheme ``dpapi``,
    Chrome < 80) is decrypted with ``mk_pool`` directly. ``v20`` (App-Bound) is reported
    but not decrypted here.
    """
    scheme = value_scheme(value)
    if scheme == 'v10':
        return decrypt_gcm(value, key), scheme
    if scheme == 'dpapi' and mk_pool is not None:
        blob = DpapiBlob(bytes(value))
        master_key = mk_pool.get_key(blob.mk_guid)
        return (blob.decrypt(master_key, entropy=entropy) if master_key else None), scheme
    return None, scheme


def strip_cookie_host_hash(plaintext, cookies_db_version):
    """Remove the 32-byte SHA-256(host_key) prefix present at Cookies schema version >= 24."""
    if plaintext is None:
        return None
    if (cookies_db_version is not None
            and cookies_db_version >= _COOKIE_HOST_HASH_MIN_DB_VERSION
            and len(plaintext) >= _COOKIE_HOST_HASH_LEN):
        return plaintext[_COOKIE_HOST_HASH_LEN:]
    return plaintext
